using System.Net;
using System.Text.Json;
using System.Text.RegularExpressions;

using Xunit;

/// <summary>
/// The website, held to the repository it describes.
///
/// <para>Three of these pages are generated by <c>build/Make-Pages.mjs</c> from Markdown, and that
/// generator is run BY HAND. Nothing in CI runs it, because the site has no build step - what is
/// committed under <c>website/public</c> is exactly what Netlify serves. So the failure mode this
/// class exists for is somebody editing <c>PRIVACY.md</c>, committing, and shipping a privacy page
/// that still says the old thing. A published policy that disagrees with the policy in the
/// repository is worse than having neither.</para>
///
/// <para>The tests below therefore compare the SHIPPED bytes against their sources rather than
/// reading the generator and believing it. A test that only checked the generator's source would
/// pass on the day somebody forgot to run it, which is the only day it matters.</para>
/// </summary>
public class WebsiteTests
{
    private const string Site = "https://findra-search.netlify.app";

    private static readonly string Index = Repo.Read("website/public/index.html");
    private static readonly string NotFound = Repo.Read("website/public/404.html");
    private static readonly string Llms = Repo.Read("website/public/llms.txt");
    private static readonly string Sitemap = Repo.Read("website/public/sitemap.xml");
    private static readonly string Netlify = Repo.Read("netlify.toml");

    /// <summary>Every generated page, with the Markdown it is generated from and the Markdown twin
    /// published beside it. This list is the same one <c>build/Make-Pages.mjs</c> holds; if a
    /// further page is added there and not here, the sitemap test below is what notices.</summary>
    public static TheoryData<string, string> Generated => new()
    {
        { "privacy", "PRIVACY.md" },
        { "about", "website/content/about.md" },
        { "contact", "website/content/contact.md" },
        { "code-signing", "docs/code-signing-policy.md" },
    };

    // ------------------------------------------------------------------ the pages say their source

    /// <summary>
    /// The published Markdown twin is the source file, byte for byte.
    ///
    /// <para>This is the strongest assertion available and it is nearly free, so it comes first.
    /// The twin exists so that an agent asking for <c>text/markdown</c>, and a person who would
    /// rather read the file, get the real policy rather than a paraphrase of it - and a copy that
    /// has drifted is a paraphrase whether or not anybody meant it to be.</para>
    /// </summary>
    [Theory]
    [MemberData(nameof(Generated))]
    public void ThePublishedMarkdownIsTheSourceFileAndNotACopyThatHasDrifted(string slug, string source)
    {
        Assert.Equal(Repo.Read(source), Repo.Read($"website/public/{slug}.md"));
    }

    /// <summary>
    /// The generated HTML page carries every sentence its Markdown does.
    ///
    /// <para>Compared as prose rather than as markup: the generator turns <c>##</c> into
    /// <c>&lt;h2&gt;</c> and rewraps hard-wrapped paragraphs, so the bytes cannot match and should
    /// not be expected to. What must match is what the page SAYS.</para>
    ///
    /// <para>The document's own H1 is excluded on both sides, because the page deliberately carries
    /// a different one - <c>PRIVACY.md</c> opens "Privacy" for somebody who came looking for the
    /// policy, and the page opens "Nothing leaves your machine, except one request" for somebody
    /// deciding whether to trust the product.</para>
    /// </summary>
    [Theory]
    [MemberData(nameof(Generated))]
    public void EverySentenceInTheMarkdownReachesThePage(string slug, string source)
    {
        string page = Unbroken(Prose(Repo.Read($"website/public/{slug}/index.html")));

        foreach (string sentence in Sentences(Repo.Read(source)))
        {
            Assert.True(
                page.Contains(sentence, StringComparison.Ordinal),
                $"website/public/{slug}/index.html does not carry this sentence from {source}, so " +
                $"the two have drifted apart - run `node build/Make-Pages.mjs`:\n  {sentence}");
        }
    }

    /// <summary>
    /// And nothing was added to the page that the Markdown does not say.
    ///
    /// <para>The opposite direction matters as much and is the easier one to get wrong: an
    /// obligation invented in HTML, or a caveat quietly dropped from the Markdown, both leave the
    /// two disagreeing. The page's own shell - navigation, footer, the heading and the two chips -
    /// is not prose from the source and is excluded by reading only the <c>&lt;article&gt;</c>.</para>
    /// </summary>
    [Theory]
    [MemberData(nameof(Generated))]
    public void ThePageSaysNothingTheMarkdownDoesNot(string slug, string source)
    {
        string markdown = Unbroken(Strip(Repo.Read(source)));

        foreach (string sentence in Sentences(Article(Repo.Read($"website/public/{slug}/index.html"))))
        {
            Assert.True(
                markdown.Contains(sentence, StringComparison.Ordinal),
                $"website/public/{slug}/index.html says something {source} does not:\n  {sentence}");
        }
    }

    // ------------------------------------------------------------------ the share card

    /// <summary>
    /// The card the social platforms crop to is really 1200 by 630, and the page says so.
    ///
    /// <para>Both halves are load-bearing. The dimensions are declared because WhatsApp will not
    /// fetch an image to measure it and shows no preview at all rather than guess; and a declared
    /// size that disagrees with the file is worse than none, because the platforms lay the card out
    /// from what was declared and then paint something a different shape into it.</para>
    ///
    /// <para>The previous <c>og:image</c> was a product screenshot at 820 by 626 - 1.31:1 against
    /// the 1.91:1 X and Facebook crop to - which is the defect this asserts against.</para>
    /// </summary>
    [Fact]
    public void TheShareCardIsTheSizeThePageDeclaresAndTheSizeThePlatformsCropTo()
    {
        (int width, int height) = PngSize("website/public/share/card.png");
        Assert.Equal(1200, width);
        Assert.Equal(630, height);

        Assert.Contains($@"<meta property=""og:image"" content=""{Site}/share/card.png"">", Index, StringComparison.Ordinal);
        Assert.Contains(@"<meta property=""og:image:width"" content=""1200"">", Index, StringComparison.Ordinal);
        Assert.Contains(@"<meta property=""og:image:height"" content=""630"">", Index, StringComparison.Ordinal);

        // An image with no alt text is an image an agent, and anybody using a screen reader on a
        // shared link, is told nothing about.
        Assert.Matches(@"<meta property=""og:image:alt"" content=""[^""]{20,}"">", Index);

        // The square exists only to be posted by hand: Instagram reads no Open Graph at all. It
        // is still held to its size, because a feed crops anything that is not square.
        (int side, int tall) = PngSize("website/public/share/square.png");
        Assert.Equal(1080, side);
        Assert.Equal(1080, tall);
    }

    /// <summary>Every page declares the whole Open Graph set, not the half that happens to be
    /// enough for one platform. A page missing <c>og:site_name</c> or <c>og:locale</c> is a page an
    /// entity resolver has to guess at.</summary>
    [Theory]
    [InlineData("website/public/index.html")]
    [InlineData("website/public/privacy/index.html")]
    [InlineData("website/public/about/index.html")]
    [InlineData("website/public/contact/index.html")]
    [InlineData("website/public/code-signing/index.html")]
    public void EveryPageCarriesTheWholeOpenGraphSet(string path)
    {
        string html = Repo.Read(path);
        foreach (string property in new[]
                 { "og:type", "og:site_name", "og:locale", "og:url", "og:title", "og:description",
                   "og:image", "og:image:width", "og:image:height", "og:image:alt" })
        {
            Assert.Contains($@"property=""{property}""", html, StringComparison.Ordinal);
        }

        Assert.Contains(@"name=""twitter:card"" content=""summary_large_image""", html, StringComparison.Ordinal);
        Assert.Contains(@"<link rel=""canonical""", html, StringComparison.Ordinal);
        Assert.Contains(@"<html lang=""en"">", html, StringComparison.Ordinal);
    }

    // ------------------------------------------------------------------ structured data

    /// <summary>
    /// The homepage's JSON-LD parses, and every fact in it is a fact stated elsewhere.
    ///
    /// <para>Structured data is the one part of a page nobody proofreads, because nobody sees it.
    /// A version number left behind at 0.1.0 after a release, or a price that says the product
    /// costs money, is wrong in the machine-readable copy while the human-readable one beside it is
    /// right.</para>
    /// </summary>
    [Fact]
    public void TheStructuredDataParsesAndAgreesWithTheRepository()
    {
        Match block = Regex.Match(
            Index, @"<script type=""application/ld\+json"">(?<json>.*?)</script>", RegexOptions.Singleline);
        Assert.True(block.Success, "the homepage carries no JSON-LD");

        using JsonDocument document = JsonDocument.Parse(block.Groups["json"].Value);
        JsonElement graph = document.RootElement.GetProperty("@graph");

        JsonElement app = graph.EnumerateArray().Single(n => n.GetProperty("@type").GetString() == "SoftwareApplication");
        Assert.Equal("Findra", app.GetProperty("name").GetString());
        Assert.Equal($"{Site}/", app.GetProperty("url").GetString());

        // The version lives in Directory.Build.props and nowhere else. This is a second place it
        // is written down, so this is the test that keeps it from becoming a second source.
        string version = Regex.Match(Repo.Read("Directory.Build.props"), @"<Version>([^<]+)</Version>").Groups[1].Value;
        Assert.Equal(version, app.GetProperty("softwareVersion").GetString());

        // Free means free, and a price of anything else here is a claim the whole site contradicts.
        Assert.Equal("0", app.GetProperty("offers").GetProperty("price").GetString());

        // Availability and downloadUrl are the two fields that go stale the day a release lands,
        // and neither is visible on the page - which is exactly why they sat wrong. PreOrder says
        // "you cannot have this yet" to every machine that reads the page, and a downloadUrl
        // pointing at the repository root is a page with no download on it.
        //
        // Coupled to the same fact the README's install paragraph is coupled to: a numbered
        // section in CHANGELOG.md, which appears when a release is cut and never before. Nothing
        // on the page changes when it does, so a person will not notice; this will.
        bool released = Regex.IsMatch(Repo.Read("CHANGELOG.md"), @"(?m)^##\s+\[\d+\.\d+\.\d+\]");
        Assert.Equal(released ? "https://schema.org/InStock" : "https://schema.org/PreOrder",
                     app.GetProperty("offers").GetProperty("availability").GetString());
        if (released)
        {
            Assert.Contains("/releases", app.GetProperty("downloadUrl").GetString()!,
                            StringComparison.Ordinal);
        }
        Assert.True(app.GetProperty("isAccessibleForFree").GetBoolean());
        Assert.Contains("Windows", app.GetProperty("operatingSystem").GetString()!, StringComparison.Ordinal);

        // The person named here is the person the About page names, and the handle beside it is
        // the one the licence, the NOTICE and the repository URL all use. Both are needed: an
        // entity resolver matching "Liraz Amir" to this project has only the alternateName to go
        // on, and one matching "blakazulu" has only the name.
        JsonElement person = graph.EnumerateArray().Single(n => n.GetProperty("@type").GetString() == "Person");
        Assert.Equal("Liraz Amir", person.GetProperty("name").GetString());
        Assert.Equal("blakazulu", person.GetProperty("alternateName").GetString());
        Assert.Contains("Liraz Amir", Repo.Read("website/content/about.md"), StringComparison.Ordinal);
        Assert.True(person.TryGetProperty("contactPoint", out _), "no contactPoint, which is the point of the Person node");
    }

    /// <summary>
    /// No page invents a postal address or a telephone number.
    ///
    /// <para>This is a refusal rather than an omission, and it is written down as a test because it
    /// looks like a gap. Readiness checks score an Organization node higher when it carries a
    /// <c>PostalAddress</c> and a <c>telephone</c>, and the obvious way to make one pass is to put
    /// something in those fields. Findra is one person and an open repository; a switchboard nobody
    /// answers, or a home address, would be the only dishonest thing on the site.</para>
    /// </summary>
    [Fact]
    public void NothingOnTheSiteInventsAPostalAddressOrATelephoneNumber()
    {
        foreach (string path in new[]
                 { "website/public/index.html", "website/public/contact/index.html",
                   "website/public/about/index.html", "website/public/privacy/index.html",
                   "website/public/llms.txt", "website/public/code-signing/index.html",
                   "website/public/404.html", "website/public/index.md", "website/public/about.md",
                   "website/public/contact.md", "website/public/privacy.md",
                   "website/public/code-signing.md", "website/content/home.md",
                   "website/content/about.md", "website/content/contact.md" })
        {
            // Comments only. The structured data is deliberately NOT stripped: an address added
            // to the JSON-LD is exactly the thing this test exists to catch, and a check that read
            // only the visible text could not see it.
            string text = WithoutComments(Repo.Read(path));
            Assert.DoesNotContain("PostalAddress", text, StringComparison.Ordinal);
            Assert.DoesNotContain("streetAddress", text, StringComparison.Ordinal);
            Assert.DoesNotContain("\"telephone\"", text, StringComparison.Ordinal);
        }

        // And the contact page says so out loud, rather than leaving a reader to wonder whether
        // the details were merely forgotten.
        string contact = Flat(Repo.Read("website/content/contact.md"));
        Assert.Contains("no phone number and no postal address", contact, StringComparison.OrdinalIgnoreCase);
    }

    // ------------------------------------------------------------------ finding your way

    /// <summary>
    /// The sitemap lists every page the site has, and every page it lists exists.
    ///
    /// <para>Both directions. A sitemap missing a page is a page nothing will index; a sitemap
    /// naming a page that is not there is a 404 handed to a crawler on the site's own authority.
    /// </para>
    /// </summary>
    [Fact]
    public void TheSitemapAndThePagesOnDiskAreTheSameSet()
    {
        HashSet<string> listed = Regex.Matches(Sitemap, @"<loc>([^<]+)</loc>")
            .Select(m => m.Groups[1].Value)
            .ToHashSet(StringComparer.Ordinal);

        HashSet<string> onDisk = new(StringComparer.Ordinal) { $"{Site}/" };
        foreach (string slug in new[] { "privacy", "about", "contact", "code-signing" })
        {
            Assert.True(Repo.Exists($"website/public/{slug}/index.html"), $"/{slug}/ is missing");
            onDisk.Add($"{Site}/{slug}/");
        }

        Assert.Equal(onDisk.OrderBy(u => u, StringComparer.Ordinal),
                     listed.OrderBy(u => u, StringComparer.Ordinal));

        // 404.html is deliberately absent from the sitemap and says so with a robots meta.
        Assert.Contains(@"<meta name=""robots"" content=""noindex"">", NotFound, StringComparison.Ordinal);
    }

    /// <summary>
    /// The 404 page is a map rather than an apology.
    ///
    /// <para>Netlify serves this file, with a real 404 status, for any path that does not exist.
    /// Before it existed the platform's own default page was served - which carries a
    /// <c>netlify.new</c> referral link in its body, on a site whose whole argument is that nothing
    /// is reaching out anywhere. The reader here is a person who mistyped or an agent that guessed
    /// a URL, and both need the list of real ones.</para>
    /// </summary>
    [Fact]
    public void TheNotFoundPageNamesEveryPlaceAReaderCouldGoInstead()
    {
        foreach (string href in new[]
                 { "\"/\"", "\"/about/\"", "\"/contact/\"", "\"/privacy/\"",
                   "\"/code-signing/\"",
                   "\"/llms.txt\"", "\"/sitemap.xml\"", "\"/robots.txt\"" })
        {
            Assert.Contains($"href={href}", NotFound, StringComparison.Ordinal);
        }

        // Nothing WE author advertises the platform the site happens to be hosted on. That is the
        // whole of what this can promise, and the limit is worth stating: Netlify injects a
        // hosting-provider meta tag and a netlify.new referral comment into every HTML response on
        // the current plan, after these bytes leave the repository. The live page is not clean and
        // no test here can make it so - a plan or a platform setting can. What this catches is the
        // thing that IS in our hands: a referral link somebody pastes into a file.
        //
        // Comments are excluded because two of them explain this very situation.
        Assert.DoesNotContain("netlify.new", WithoutComments(NotFound), StringComparison.OrdinalIgnoreCase);
        Assert.DoesNotContain("netlify.new", WithoutComments(Index), StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>
    /// The homepage's footer links to the site's own pages rather than to files on GitHub.
    ///
    /// <para>The privacy policy used to be reachable only as a Markdown file in the repository,
    /// which is a fine place for it to live and a poor place to send somebody who is deciding
    /// whether to install the product.</para>
    /// </summary>
    [Fact]
    public void TheFooterSendsAReaderToThePagesAndNotToRawFiles()
    {
        Assert.Contains(@"<a href=""/privacy/"">Privacy</a>", Index, StringComparison.Ordinal);
        Assert.Contains(@"<a href=""/about/"">About</a>", Index, StringComparison.Ordinal);
        Assert.Contains(@"<a href=""/contact/"">Contact</a>", Index, StringComparison.Ordinal);
        Assert.DoesNotContain("blob/main/PRIVACY.md", Index, StringComparison.Ordinal);

        // The SignPath Foundation's terms require the TERM "Code signing policy" on the project's
        // home page and on its download page, as a section header or a link to a dedicated page.
        // Both are links here and both are asserted, because this page is hand-written while every
        // other page's footer comes out of build/Make-Pages.mjs - so the front page is the one
        // place the two can fall out of step. The download half sits in the install section,
        // beside the sentence saying Findra is not signed yet.
        Assert.Contains(@"<a href=""/code-signing/"">Code signing policy</a>", Index,
                        StringComparison.Ordinal);
        Assert.Equal(2, Regex.Matches(Index, "Code signing policy").Count);
    }

    // ------------------------------------------------------------------ what agents are told

    /// <summary>
    /// <c>llms.txt</c> says when to reach for Findra and when not to, and does not claim to be
    /// something Findra is not.
    ///
    /// <para>The "when not to" half is the half worth testing. Findra is a desktop application
    /// with no API, no accounts and no server, hosted as static files on a platform that publishes
    /// its own MCP server, CLI and SDKs - and a readiness scan of this domain credited every one of
    /// those to Findra. Saying plainly that there is nothing to call is what stops that.</para>
    /// </summary>
    [Fact]
    public void TheAgentInstructionsSayWhenToUseFindraAndWhatItIsNot()
    {
        Assert.Contains("## When to use this", Llms, StringComparison.Ordinal);
        Assert.Contains("Do not reach for Findra when", Llms, StringComparison.Ordinal);

        string flat = Flat(Llms);
        Assert.Contains("no API", flat, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("no MCP server", flat, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("Netlify's own MCP server, CLI and SDKs are the host's, not Findra's",
                        flat, StringComparison.Ordinal);

        // Every page, and every Markdown twin, is named - otherwise this file is a summary rather
        // than an index, and an agent still has to guess at URLs.
        foreach (string url in new[]
                 { $"{Site}/", $"{Site}/about/", $"{Site}/contact/", $"{Site}/privacy/",
                   $"{Site}/index.md", $"{Site}/about.md", $"{Site}/contact.md", $"{Site}/privacy.md" })
        {
            Assert.Contains(url, Llms, StringComparison.Ordinal);
        }
    }

    /// <summary>
    /// The Markdown negotiation is wired end to end: the edge function offers exactly the pages
    /// that have a twin, and the twins are served with <c>Vary: Accept</c>.
    ///
    /// <para><c>Vary</c> is the part that looks like a detail and is not. Without it a CDN caches
    /// whichever variant it saw first and serves that to everybody after - so a browser gets
    /// Markdown, or an agent gets HTML, depending on which one knocked first.</para>
    /// </summary>
    [Fact]
    public void MarkdownNegotiationCoversEveryPageThatHasAMarkdownTwin()
    {
        string edge = Repo.Read("netlify/edge-functions/markdown.ts");

        foreach ((string path, string twin) in new[]
                 { ("/", "/index.md"), ("/about/", "/about.md"),
                   ("/contact/", "/contact.md"), ("/privacy/", "/privacy.md"),
                   ("/code-signing/", "/code-signing.md") })
        {
            Assert.Contains($"'{path}': '{twin}'", edge, StringComparison.Ordinal);
            Assert.True(Repo.Exists($"website/public{twin}"), $"{twin} is declared but not published");
            // Declared in `config.path` too, or the function is never invoked for that URL at all.
            Assert.Contains($"'{path}'", edge.Split("export const config")[1], StringComparison.Ordinal);
        }

        Assert.Contains("Vary = \"Accept, Accept-Encoding\"", Netlify, StringComparison.Ordinal);
        Assert.Contains("Content-Type = \"text/markdown; charset=utf-8\"", Netlify, StringComparison.Ordinal);

        // A browser sends `*/*;q=0.8`, which matches text/markdown. A negotiator that does not
        // weigh the q values hands Markdown to every human visitor.
        Assert.Contains("q=", edge, StringComparison.Ordinal);
        Assert.Contains("markdown > html", edge, StringComparison.Ordinal);
    }

    /// <summary>
    /// Nothing lives in the edge functions directory except edge functions.
    ///
    /// <para>Netlify deploys every top-level file in <c>netlify/edge-functions/</c> AS an edge
    /// function - .js, .ts, .jsx, .tsx and .mjs alike - and an edge function with no default export
    /// fails the build. This is written down as a test because of what that failure looks like from
    /// outside: the deploy does not half-work and the site does not break. It simply never happens,
    /// and the previous commit goes on being served, so everything looks fine until somebody
    /// notices that a change pushed some time ago is not live.</para>
    ///
    /// <para>That is exactly what a test file placed next to the function it tests did here. Helper
    /// files can live in a SUBDIRECTORY of that folder, which Netlify does not deploy; the node
    /// test lives in <c>tests/edge/</c> with the rest of the tests.</para>
    /// </summary>
    [Fact]
    public void TheEdgeFunctionsDirectoryHoldsNothingButEdgeFunctions()
    {
        string[] deployed = Directory.GetFiles(Repo.Path_("netlify/edge-functions"))
            .Where(f => new[] { ".js", ".ts", ".jsx", ".tsx", ".mjs" }
                .Contains(Path.GetExtension(f), StringComparer.OrdinalIgnoreCase))
            .ToArray();

        Assert.NotEmpty(deployed);

        foreach (string file in deployed)
        {
            string source = File.ReadAllText(file);
            Assert.True(
                source.Contains("export default", StringComparison.Ordinal),
                $"netlify/edge-functions/{Path.GetFileName(file)} has no default export, so Netlify " +
                "will fail the whole deploy trying to bundle it as an edge function - and a deploy " +
                "that never happens leaves the previous commit live with nothing to show it went " +
                "wrong. Only real edge functions belong in that directory.");

            // A file Netlify runs on Deno cannot use node's globals. `process.exit` in one is the
            // same mistake in a different disguise.
            Assert.DoesNotContain("process.exit", source, StringComparison.Ordinal);
        }
    }

    /// <summary>The site makes no comparative claim against a named competitor - the same rule the
    /// README and the winget listing are held to, applied to three new pages of prose.</summary>
    [Fact]
    public void TheNewPagesNameNoCompetitor()
    {
        foreach (string path in new[]
                 { "website/content/about.md", "website/content/contact.md",
                   "website/content/home.md", "website/public/llms.txt", "website/public/404.html",
                   "website/public/index.html", "PRIVACY.md", "docs/code-signing-policy.md",
                   "website/public/about/index.html", "website/public/contact/index.html",
                   "website/public/privacy/index.html", "website/public/code-signing/index.html",
                   "website/public/index.md", "website/public/about.md", "website/public/contact.md",
                   "website/public/privacy.md", "website/public/code-signing.md" })
        {
            string text = Repo.Read(path);
            foreach (string name in Repo.Competitors)
            {
                Assert.DoesNotContain(name, text, StringComparison.OrdinalIgnoreCase);
            }
        }
    }

    // ------------------------------------------------------------------ reading the files

    /// <summary>A PNG's declared size, from the IHDR chunk, which is always the first one.</summary>
    private static (int Width, int Height) PngSize(string relative)
    {
        byte[] bytes = File.ReadAllBytes(Repo.Path_(relative));
        Assert.True(bytes.Length > 24, $"{relative} is too short to be a PNG");
        return (System.Buffers.Binary.BinaryPrimitives.ReadInt32BigEndian(bytes.AsSpan(16, 4)),
                System.Buffers.Binary.BinaryPrimitives.ReadInt32BigEndian(bytes.AsSpan(20, 4)));
    }

    /// <summary>The body of a generated page: what is inside its one <c>&lt;article&gt;</c>, which
    /// is the part that came from the Markdown, without the shell around it.</summary>
    private static string Article(string html)
    {
        Match m = Regex.Match(html, @"<article class=""doc"">(?<body>.*?)</article>", RegexOptions.Singleline);
        Assert.True(m.Success, "the page has no <article class=\"doc\">, so it was not generated by Make-Pages.mjs");
        return Tags(m.Groups["body"].Value);
    }

    /// <summary>A whole page as readable text.</summary>
    private static string Prose(string html) => Tags(html);

    /// <summary>HTML comments removed, and nothing else. Used by the two tests that assert a
    /// string is ABSENT: a comment saying why the page carries no postal address is not the page
    /// carrying one, and neither is a comment recording what this file replaced. Everything else,
    /// the structured data included, stays - because that is where such a thing would appear.
    /// </summary>

    // ------------------------------------------------------------------ the site quotes the repository

    /// <summary>
    /// The site's benchmark table is the README's benchmark table.
    ///
    /// <para>Both are pasted from the same <c>--searchbench</c> run and both say so on the page.
    /// Two copies of one measurement is two answers waiting to differ, and they did: a run taken
    /// against a debug build with ten documents in the content index went on being served from the
    /// front page, the Markdown twin and the share card for as long as it took somebody to read
    /// both pages side by side. The README is the source, because that is where the whole fragment
    /// is pasted whole; the site quotes five rows out of it.</para>
    ///
    /// <para>The direction of the error is worth recording: the stale numbers UNDERSTATED the
    /// product. A wrong number that flatters is caught by the person it embarrasses; one that does
    /// not is caught by nobody, which is what a test is for.</para>
    /// </summary>
    [Fact]
    public void TheSiteQuotesTheReadmesOwnBenchmarkNumbers()
    {
        string readme = Repo.Read("README.md");
        string home = Repo.Read("website/content/home.md");

        foreach (string query in new[] { "config", "report", "readme", "invoice", "sunset" })
        {
            // Every column, not the first one. Guarding p50 alone left p95, the index scan, the
            // worst case and the hit count free to say anything at all.
            Match row = Regex.Match(
                readme,
                $@"(?m)^\|\s{query}\s\|\s([\d.]+) ms\s\|\s([\d.]+) ms\s\|\s([\d.]+) ms\s\|\s[\d.]+ ms\s\|\s([\d.]+) ms\s\|\s(\d+)\s\|");
            Assert.True(row.Success, $"the README's name-query table has no row for {query}");

            string p50 = row.Groups[1].Value, p95 = row.Groups[2].Value;
            string scan = row.Groups[3].Value, worst = row.Groups[4].Value, hits = row.Groups[5].Value;

            Assert.Contains($"| {query} | {p50} ms | {p95} ms | {scan} ms | {worst} ms | {hits} |",
                            home, StringComparison.Ordinal);

            // The whole ROW, not just the number. ">0.33 ms<" also matches the stat card above the
            // table, so a table cell left behind at the old figure passed while the card carried
            // the new one - which is the same two-copies-of-one-number defect one level down.
            Assert.Contains(
                $@"<tr><td>{query}</td><td class=""num"">{p50} ms</td><td class=""num"">{p95} ms</td>" +
                $@"<td class=""num"">{scan} ms</td><td class=""num"">{worst} ms</td><td>{hits}</td></tr>",
                Index, StringComparison.Ordinal);
        }

        // The headline figure is repeated in prose, in the share card the icon generator bakes,
        // in the alt text the page generator emits, and in the file agents read first. The share
        // card is the copy that actually went stale, and nothing was reading it.
        string headline = Regex.Match(readme, @"(?m)^\|\sconfig\s\|\s([\d.]+) ms").Groups[1].Value;
        string p50Headline = headline;

        // The range and the worst sample are derived, never typed. The five name-query rows give
        // both: the slowest median is the top of the published range, and the largest Worst cell
        // is the figure the prose calls the worst single sample.
        MatchCollection rows = Regex.Matches(
            readme,
            @"(?m)^\|\s\w+\s\|\s([\d.]+) ms\s\|\s[\d.]+ ms\s\|\s[\d.]+ ms\s\|\s[\d.]+ ms\s\|\s([\d.]+) ms\s\|");
        Assert.Equal(5, rows.Count);

        double[] medians = rows.Select(m => double.Parse(m.Groups[1].Value)).ToArray();
        double[] worsts = rows.Select(m => double.Parse(m.Groups[2].Value)).ToArray();
        string range = $"{medians.Min():0.00} to {medians.Max():0.00} ms";
        string worstSample = $"{worsts.Max():0.00} ms";
        foreach (string path in new[]
                 { "build/Make-Icon.mjs", "build/Make-Pages.mjs",
                   "website/public/llms.txt", "website/public/index.md" })
        {
            Assert.Contains(headline, Repo.Read(path), StringComparison.Ordinal);
        }

        // Every surface that publishes the range publishes the derived one. app.js is in the
        // list because the ticker now carries the figures and no test read that file at all.
        foreach (string path in new[]
                 { "website/public/index.html", "website/content/home.md", "website/public/index.md",
                   "website/public/llms.txt", "build/Make-Icon.mjs", "build/Make-Pages.mjs" })
        {
            // With the word, not just the figures: "0.33 to 2.05 ms" is a range of MEDIANS and
            // the worst sample sits above it, so the bare range is the claim that was retired.
            Assert.Contains($"{range} median", Regex.Replace(Repo.Read(path), @"\s+", " "),
                            StringComparison.Ordinal);
        }

        Assert.Contains($"{range.Replace(" to ", "-")} MEDIAN".ToUpperInvariant(),
                        Repo.Read("website/public/app.js").ToUpperInvariant(), StringComparison.Ordinal);

        foreach (string path in new[]
                 { "website/public/index.html", "website/content/home.md",
                   "website/public/index.md", "website/public/llms.txt" })
        {
            Assert.Contains($"worst single sample across the five measured name queries was {worstSample}",
                            Regex.Replace(Repo.Read(path), @"\s+", " "), StringComparison.Ordinal);
        }

        Assert.Contains($"The slowest of the five medians was {medians.Max():0.00} ms",
                        Regex.Replace(Index, @"\s+", " "), StringComparison.Ordinal);

        // The four stat cards sit above the table and were bound by nothing, which is precisely
        // where the last drift landed: 2.8 s, 73.1 MB and 1,573,675 all lived here.
        Match volumes = Regex.Match(readme, @"(?m)^\|\sC:\s\|\s([\d,]+)\s\|\s([\d.]+) MB\s\|\s([\d,]+) ms\s\|");
        Assert.True(volumes.Success, "the README has no volumes row");

        string names = volumes.Groups[1].Value, resident = volumes.Groups[2].Value;
        double seconds = double.Parse(volumes.Groups[3].Value.Replace(",", "")) / 1000.0;

        string cards = Between(Index, @"<div class=""stat-row"">", "</div>\n\n      <div class=\"table-wrap");
        Assert.Contains($"{names} names", cards, StringComparison.Ordinal);
        Assert.Contains($@"<span class=""v"">{p50Headline} ms</span>", cards, StringComparison.Ordinal);

        // The stat card names one query. Whatever else it says, it must not go on to credit that
        // query with a figure drawn from the whole set - which is exactly how it read before.
        Assert.DoesNotMatch($@"""config""[^.]*{Regex.Escape(worstSample)}", Regex.Replace(cards, @"\s+", " "));

        // Every latency the page prints in the mock window is one the benchmark produced. Three
        // invented figures lived there under a heading promising the opposite.
        foreach (Match shown in Regex.Matches(Index, @"<span class=""ms"">([\d.]+) ms</span>"))
        {
            Assert.Contains(shown.Groups[1].Value, medians.Select(m => $"{m:0.00}"));
        }
        Assert.Contains($@"<span class=""v"">{resident} MB</span>", Index, StringComparison.Ordinal);
        Assert.Contains($@"<span class=""v"">{seconds:0.0} s</span>", Index, StringComparison.Ordinal);

        // index.md is a copy of home.md that build/Make-Pages.mjs makes. Nothing asserted it.
        Assert.Equal(home, Repo.Read("website/public/index.md"));
    }

    /// <summary>
    /// No surface still says Findra is unreleased once a release exists.
    ///
    /// <para>The README is already coupled to this fact by
    /// <c>ReadmeTests.TheReadmeDoesNotStillSayFindraIsNotReadyToInstall</c>, and the structured
    /// data by <c>availability</c> above. The About page was not, and so it went on telling every
    /// reader and every crawler that the first release had not been tagged and that building from
    /// source was the route that worked - on the page an entity resolver reads for status, weeks
    /// after the tag. The fact that moves is a numbered section in the changelog, which is the
    /// same fact the other two are keyed off.</para>
    /// </summary>
    [Fact]
    public void NoPageStillSaysTheFirstReleaseHasNotBeenTagged()
    {
        bool released = Regex.IsMatch(Repo.Read("CHANGELOG.md"), @"(?m)^##\s+\[\d+\.\d+\.\d+\]");
        if (!released)
        {
            return;
        }

        foreach (string path in new[]
                 { "website/content/about.md", "website/content/home.md", "website/public/about.md",
                   "website/public/index.md", "website/public/llms.txt", "website/public/index.html" })
        {
            string text = Repo.Read(path);
            Assert.DoesNotContain("has not been tagged", text, StringComparison.OrdinalIgnoreCase);
            Assert.DoesNotContain("not been released", text, StringComparison.OrdinalIgnoreCase);
            Assert.DoesNotContain("coming soon", text, StringComparison.OrdinalIgnoreCase);

            // A blocklist only catches the three phrasings somebody happened to think of;
            // "not yet released" or "until the first tag" would walk straight through it.
            // Asserting the positive fact cannot be routed around by rewording.
            Assert.Contains("winget install blakazulu.Findra", text, StringComparison.Ordinal);
        }
    }

    /// <summary>
    /// Every capability size the site quotes is the size the model store actually holds.
    ///
    /// <para>The meaning model moved from a quantised export to full precision and its download
    /// went from 270 MB to 1.04 GB. The front page followed; the Markdown twin, <c>home.md</c> and
    /// <c>llms.txt</c> did not, so the machine-readable half of the site - the half an answer
    /// engine ingests first - understated the total download by 28% and one capability by four
    /// times, while the human-readable half beside it was right.</para>
    ///
    /// <para>The figures are asserted as strings rather than recomputed from
    /// <c>Capabilities.OwnModels</c> on purpose: what is being guarded is that the four surfaces
    /// agree with each other and with the README, and a test that recomputed them would pass on a
    /// day when every surface was equally wrong.</para>
    /// </summary>
    [Fact]
    public void EverySurfaceQuotesTheSameCapabilitySizes()
    {
        string[] surfaces = { "website/content/home.md", "website/public/index.md",
                              "website/public/llms.txt", "website/public/index.html" };

        foreach (string path in surfaces)
        {
            string text = Repo.Read(path);
            foreach (string size in new[] { "629 MB", "1.04 GB", "547 MB", "1.51 GB", "3.7 GB" })
            {
                Assert.Contains(size, text, StringComparison.Ordinal);
            }

            // The two figures the fp32 change invalidated. Either one appearing beside a
            // capability name means a surface was left behind again.
            Assert.DoesNotContain("270 MB", text, StringComparison.Ordinal);
            Assert.DoesNotContain("2.9 GB", text, StringComparison.Ordinal);
            Assert.DoesNotContain("2.93 GB", text, StringComparison.Ordinal);
        }

        // Presence is not attachment: with the five figures merely present, swapping the photo
        // and speech numbers over left every assertion above satisfied. Each number is bound to
        // the capability it prices, in whichever shape that surface writes it.
        foreach (string path in new[] { "website/public/index.html", "website/public/llms.txt" })
        {
            // Collapsed: llms.txt wraps its prose, and a phrase split over two lines is not a
            // different phrase.
            string text = Regex.Replace(Repo.Read(path), @"\s+", " ");
            Assert.Contains("629 MB for photos and video", text, StringComparison.Ordinal);
            Assert.Contains("1.04 GB for meaning in documents", text, StringComparison.Ordinal);
            Assert.Contains("547 MB for speech", text, StringComparison.Ordinal);
            Assert.Contains("1.51 GB for the Hebrew", text, StringComparison.Ordinal);

            // The same figures again in the answers, where they were unbound on these two
            // surfaces while being bound on the Markdown twins.
            Assert.Contains("629 MB download", text, StringComparison.Ordinal);
            Assert.Contains("547 MB on top of them", text, StringComparison.Ordinal);
        }

        foreach (string path in new[] { "website/content/home.md", "website/public/index.md" })
        {
            string text = Regex.Replace(Repo.Read(path), @"\s+", " ");

            // These files carry the figures twice: once in the table and once in the answers.
            // Only the table was bound, so "1.51 GB for meaning in documents" in a paragraph
            // satisfied every assertion above.
            Assert.Contains("629 MB download", text, StringComparison.Ordinal);
            Assert.Contains("547 MB on top of them", text, StringComparison.Ordinal);
            Assert.Contains("1.04 GB for meaning in documents", text, StringComparison.Ordinal);
            Assert.Contains("1.51 GB for the Hebrew", text, StringComparison.Ordinal);

            Assert.Contains("| Photos and video | SigLIP-2 vision, text and spm | 629 MB |", text, StringComparison.Ordinal);
            Assert.Contains("| Meaning in documents | e5-base and e5-spm | 1.04 GB |", text, StringComparison.Ordinal);
            Assert.Contains("| Speech | Whisper turbo, plus the e5 pair | 547 MB |", text, StringComparison.Ordinal);
            Assert.Contains("| Hebrew speech | whisper-ivrit, requires speech | 1.51 GB |", text, StringComparison.Ordinal);
        }
    }

    /// <summary>
    /// Every screenshot the front page shows is declared at the size it actually is.
    ///
    /// <para><c>TheShareCardIsTheSizeThePageDeclaresAndTheSizeThePlatformsCropTo</c> already makes
    /// this argument for the share image, and the reasoning is the same one: a declared size that
    /// disagrees with the file is worse than none at all, because the browser reserves a box from
    /// the wrong aspect ratio and then reflows the page when the real image decodes. The first-run
    /// render grew from 820x820 to 820x928 and its attribute did not follow, which is 108 pixels
    /// of layout shift on the one metric a static page can fail without anybody noticing.</para>
    /// </summary>
    [Fact]
    public void EveryScreenshotIsDeclaredAtTheSizeItActuallyIs()
    {
        MatchCollection tags = Regex.Matches(
            Index, @"<img src=""(?<src>shots/[^""]+)""[^>]*?width=""(?<w>\d+)"" height=""(?<h>\d+)""");
        // Counting the images independently and requiring equality. ">= 6" against seven images
        // meant that deleting one image's width/height, or reversing them, dropped it out of the
        // match set and the test went on passing - for exactly the image it exists to check.
        int shown = Regex.Matches(Index, @"<img\s[^>]*?src=""shots/").Count;
        Assert.Equal(shown, tags.Count);
        Assert.True(tags.Count >= 6, $"expected every shot to declare a size, found {tags.Count}");

        foreach (Match tag in tags)
        {
            string relative = $"website/public/{tag.Groups["src"].Value}";
            (int width, int height) = PngSize(relative);

            Assert.True(width == int.Parse(tag.Groups["w"].Value) &&
                        height == int.Parse(tag.Groups["h"].Value),
                        $"{relative} is {width}x{height} on disk and is declared " +
                        $"{tag.Groups["w"].Value}x{tag.Groups["h"].Value} on the page");
        }
    }



    /// <summary>
    /// The front page and its Markdown twin ask the same questions, and answer them the same way.
    ///
    /// <para>Both are hand-written, so nothing generated holds them together - and they had
    /// already parted in the commit that created them, the Markdown carrying two questions the
    /// visible page did not. One of the two was whether Findra needs administrator rights, which
    /// is the largest install objection a Windows utility has, and it existed only in the layer a
    /// reader does not read.</para>
    ///
    /// <para>The generated pages have <c>EverySentenceInTheMarkdownReachesThePage</c> for this
    /// and the front page had nothing, because it is the one page the generator does not write.
    /// That is a reason to test it, not a reason to leave it alone.</para>
    /// </summary>
    [Fact]
    public void TheFrontPageAndItsMarkdownTwinAskTheSameQuestions()
    {
        string section = Between(Index, @"<section id=""questions"">", "<!-- ================= install");

        List<string> onThePage = Regex.Matches(section, @"<h3>(.*?)</h3>")
            .Select(m => WebUtility.HtmlDecode(m.Groups[1].Value).Trim())
            .ToList();

        List<string> inTheMarkdown = Regex.Matches(Repo.Read("website/content/home.md"), @"(?m)^### (.+)$")
            .Select(m => m.Groups[1].Value.Trim())
            .ToList();

        Assert.Equal(inTheMarkdown, onThePage);

        // And the structured data says what the prose says, rather than a third version of it.
        Match block = Regex.Match(
            Index, @"<script type=""application/ld\+json"">(?<json>.*?)</script>", RegexOptions.Singleline);
        using JsonDocument document = JsonDocument.Parse(block.Groups["json"].Value);
        JsonElement faq = document.RootElement.GetProperty("@graph")
            .EnumerateArray().Single(n => n.GetProperty("@type").GetString() == "FAQPage");

        Assert.Equal(onThePage,
                     faq.GetProperty("mainEntity").EnumerateArray()
                        .Select(q => q.GetProperty("name").GetString()!).ToList());

        // And the ANSWERS, which is what the summary above promises and what the first version of
        // this test did not do - so the structured copy of the answer that disclaims any Microsoft
        // relationship silently lost a paragraph while this passed.
        List<string> answersOnThePage = Regex
            .Matches(section, @"<article class=""excuse reveal"">\s*<h3>.*?</h3>\s*(.*?)\s*</article>",
                     RegexOptions.Singleline)
            .Select(m => Flatten(m.Groups[1].Value))
            .ToList();

        List<string> answersInTheGraph = faq.GetProperty("mainEntity").EnumerateArray()
            .Select(q => Flatten(q.GetProperty("acceptedAnswer").GetProperty("text").GetString()!))
            .ToList();

        Assert.Equal(answersOnThePage, answersInTheGraph);

        // And the Markdown twin's answers, which were compared to nothing at all - so the copy an
        // agent fetches could say something the page does not, which is what it had begun to do.
        string markdown = Repo.Read("website/content/home.md");
        string questionsBlock = Between(markdown, "## Questions people ask before they install it", "## Privacy");

        List<string> answersInTheMarkdown = Regex
            .Split(questionsBlock, @"(?m)^### .+$")
            .Skip(1)
            .Select(body => FlattenMarkdown(body))
            .ToList();

        Assert.Equal(answersOnThePage, answersInTheMarkdown);
    }

    /// <summary>Markup and runs of whitespace out, so two spellings of the same sentence compare
    /// equal and two different sentences do not.</summary>
    private static string Flatten(string fragment)
    {
        string text = Regex.Replace(WebUtility.HtmlDecode(Regex.Replace(fragment, "<[^>]+>", " ")), @"\s+", " ").Trim();
        // Removing an inline element leaves a space in front of whatever punctuation followed it.
        return Regex.Replace(text, @"\s+([.,;:])(?=\s|$)", "$1");
    }

    /// <summary>The same flattening for Markdown: inline code fences and bold markers out, so a
    /// sentence written for a reader compares equal to the same sentence written for a page.</summary>
    private static string FlattenMarkdown(string text) =>
        Regex.Replace(
            Regex.Replace(Regex.Replace(text, @"`([^`]*)`", "$1"), @"\*\*([^*]*)\*\*", "$1"),
            @"\s+", " ").Trim();

    /// <summary>The text between two markers, so a section can be read without a parser.</summary>
    private static string Between(string text, string start, string end)
    {
        int from = text.IndexOf(start, StringComparison.Ordinal);
        Assert.True(from >= 0, $"{start} is not on the page");
        int to = text.IndexOf(end, from, StringComparison.Ordinal);
        Assert.True(to >= 0, $"{end} does not follow {start}");
        return text[from..to];
    }


    /// <summary>
    /// Every surface that prints the winget command says the catalogue does not carry it yet.
    ///
    /// <para>`winget install blakazulu.Findra` is the primary call to action on six surfaces and
    /// it returns "No package found matching input criteria": the manifest is submitted and
    /// waiting on a moderator. An assistant repeating the command sends somebody to an error,
    /// which reads as an abandoned product rather than an unlisted one.</para>
    ///
    /// <para><see cref="Repo.WingetIsInTheCatalogue"/> is the one edit that retires this. Flip it
    /// the day the manifest merges and this test starts requiring the opposite - that no surface
    /// still hedges - so the qualification cannot be left behind either.</para>
    /// </summary>
    [Fact]
    public void EverySurfaceThatPrintsTheWingetCommandSaysWhetherItResolves()
    {
        string[] surfaces =
        {
            "README.md", "website/public/index.html", "website/content/home.md",
            "website/public/index.md", "website/content/about.md", "website/public/about.md",
            "website/public/about/index.html", "website/public/llms.txt",
        };

        foreach (string path in surfaces)
        {
            // Collapsed first: llms.txt wraps the command across a line break twice, and a
            // literal search skips every occurrence it has wrapped.
            // Comments stripped: a hedge nobody can read is not a hedge. Phrases rather than
            // the stem "moderat", which also matches "a moderate view of unsigned installers".
            string text = Regex.Replace(WithoutComments(Repo.Read(path)), @"\s+", " ");

            foreach (Match printed in Regex.Matches(text, @"winget install blakazulu\.Findra"))
            {
                // Beside the command, not merely somewhere in the file. A hedge in a footer nine
                // hundred lines below a bare call to action is not a qualification of it.
                int from = Math.Max(0, printed.Index - 200);
                int to = Math.Min(text.Length, printed.Index + printed.Length + 400);
                string near = text[from..to];

                bool hedged = near.Contains("clears moderation", StringComparison.OrdinalIgnoreCase)
                           || near.Contains("awaiting a moderator", StringComparison.OrdinalIgnoreCase)
                           || near.Contains("awaiting moderation", StringComparison.OrdinalIgnoreCase)
                           || near.Contains("does not resolve", StringComparison.OrdinalIgnoreCase);

                Assert.True(hedged == !Repo.WingetIsInTheCatalogue,
                            Repo.WingetIsInTheCatalogue
                                ? $"{path} still hedges the winget command at offset {printed.Index}, and the manifest has merged"
                                : $"{path} prints the winget command at offset {printed.Index} without saying it is not in the catalogue yet");
            }
        }
    }

    /// <summary>
    /// The site says which hardware has actually run the numbers, on every surface that prints them.
    ///
    /// <para><c>ReadmeTests.TheNumbersSayWhichHardwareHasActuallyRunThemAndWhichHasNot</c> holds
    /// the README to this and nothing held the site, though CLAUDE.md asks for both. The benchmark
    /// block gets pasted over wholesale on both, and the disclosure is what stops a reader on a
    /// machine none of it has been tried on believing the figures are theirs.</para>
    /// </summary>
    [Theory]
    [InlineData("website/public/index.html")]
    [InlineData("website/content/home.md")]
    [InlineData("website/public/index.md")]
    [InlineData("website/public/llms.txt")]
    public void EverySurfaceThatPrintsTheNumbersSaysWhichHardwareRanThem(string path)
    {
        // Collapsed, because these files wrap their prose and the sentence spans a line break
        // in three of the four.
        string text = Regex.Replace(WithoutComments(Repo.Read(path)), @"\s+", " ");
        Assert.Contains("AMD and Intel graphics have not been tested on real hardware",
                        text, StringComparison.Ordinal);
        Assert.Contains("neither has an arm64 machine", text, StringComparison.Ordinal);

        // Beside the numbers, not merely in the file. A disclosure a reader meets a screen after
        // the table it qualifies is one an extractor will never carry with the figures.
        int[] caveats = Regex.Matches(text, "AMD and Intel graphics have not been tested")
                             .Select(m => m.Index).ToArray();
        int[] machines = Regex.Matches(text, "AMD Ryzen 9 9900X3D").Select(m => m.Index).ToArray();
        if (machines.Length > 0)
        {
            // Both strings appear more than once - the machine in the structured data and again
            // under the table, the caveat in an answer and again beside the numbers. What has to
            // be true is that SOME pair of them is close enough to be read together, in either
            // direction: llms.txt states the caveat in its facts list above the answer naming the
            // machine, and index.html names the machine before the table the caveat sits under.
            int gap = caveats.Min(c => machines.Min(m => Math.Abs(m - c)));
            Assert.True(gap < 2000,
                        $"{path} never states the caveat within 2000 characters of the machine; nearest pair is {gap} apart");
        }
    }


    /// <summary>
    /// The share image's baked-in line, the alt text that describes it, and the page all say the
    /// same thing.
    ///
    /// <para>The card is drawn by <c>build/Make-Icon.mjs</c> from a constant, and the earlier
    /// guard read that constant - the generator, not the artefact - which is the same shape of
    /// mistake as reading a test's own source. It could not fail for somebody editing the
    /// constant and never running node. Binding the constant to the alt text at least makes the
    /// three written copies move together; the remaining risk, an un-regenerated PNG, is what
    /// <c>IconTests</c> covers for the mark and is called out here rather than pretended away.</para>
    /// </summary>
    [Fact]
    public void TheShareCardsLineAndTheAltTextThatDescribesItAgree()
    {
        string subline = Regex.Match(Repo.Read("build/Make-Icon.mjs"),
                                     @"const SUBLINE = \['([^']*)', '([^']*)'\];") is { Success: true } m
            ? $"{m.Groups[1].Value} {m.Groups[2].Value}"
            : throw new Xunit.Sdk.XunitException("build/Make-Icon.mjs has no SUBLINE pair");

        // The four generated pages, not only the generator that writes them: editing the template
        // and never running node leaves four shipped pages disagreeing with the card.
        // The sidecar exists only if node actually ran: Make-Icon.mjs writes it beside the PNG
        // in the same pass. Binding the constant to it closes the one hole the earlier version of
        // this guard admitted to - an edited SUBLINE with a stale card.
        Assert.Equal(subline, Repo.Read("website/public/share/card.txt").Trim());

        foreach (string path in new[]
                 { "website/public/index.html", "build/Make-Pages.mjs",
                   "website/public/about/index.html", "website/public/contact/index.html",
                   "website/public/privacy/index.html", "website/public/code-signing/index.html" })
        {
            string alt = Regex.Match(Repo.Read(path), @"og:image:alt"" content=""([^""]+)""").Groups[1].Value;
            Assert.True(alt.Length > 0, $"{path} declares no og:image:alt");
            // The whole string, so the middle cannot drift between the ends.
            Assert.Equal($"Findra. Windows Search, but it works. {subline}", alt);
        }
    }


    /// <summary>
    /// Wherever Findra says how to install it, the route that works is named first.
    ///
    /// <para>Three separate reviews found the same thing: the hedge guard checks that a
    /// qualification exists NEAR the command and can say nothing about ORDER, so every install
    /// section on the site led with `winget install blakazulu.Findra` - a command that prints
    /// "No package found matching input criteria" - and put the correction in the sentence after.
    /// An extractive summariser keeps the lead and drops the caveat, so the most-quoted answer
    /// the product has was an instruction to run something that fails.</para>
    ///
    /// <para>Keyed to the same <see cref="Repo.WingetIsInTheCatalogue"/> flag as the hedge,
    /// so one edit retires both on the day the manifest merges.</para>
    /// </summary>
    [Fact]
    public void WhereverFindraSaysHowToInstallItTheRouteThatWorksIsNamedFirst()
    {
        if (Repo.WingetIsInTheCatalogue)
        {
            return;
        }

        foreach (string path in new[]
                 { "README.md", "website/public/index.html", "website/content/home.md",
                   "website/public/index.md", "website/content/about.md", "website/public/about.md",
                   "website/public/about/index.html", "website/public/llms.txt" })
        {
            string text = Regex.Replace(WithoutComments(Repo.Read(path)), @"\s+", " ");

            // EVERY occurrence, the way the hedge guard does it. Reading only the first meant
            // index.html was judged on its JSON-LD copy, leaving the visible install section free
            // to lead with the command that fails.
            foreach (Match printed in Regex.Matches(text, @"winget install blakazulu\.Findra"))
            {
                // The releases page has to be named before the command is, in the same breath -
                // 600 characters is the width of the install paragraph on the widest surface.
                string before = text[Math.Max(0, printed.Index - 600)..printed.Index];
                Assert.True(before.Contains("releases page", StringComparison.OrdinalIgnoreCase),
                            $"{path} names the winget command at offset {printed.Index} before it names the installer that works today");
            }
        }
    }


    /// <summary>
    /// Every footer lists the same links, in the same order.
    ///
    /// <para>There are three copies of this footer and there have to be: <c>index.html</c> and
    /// <c>404.html</c> are hand-written and the other four pages come out of
    /// <c>build/Make-Pages.mjs</c>. They have drifted twice - once by two missing links, once by
    /// an Apache-2.0 link pointing at apache.org on one page and at the repository's own LICENCE
    /// on the other five - and the guard that existed asserted three link texts on one page.</para>
    ///
    /// <para>Order, not just membership. A set comparison passes on three footers listing the same
    /// eight things in three different sequences, which is what they were doing: a reader moving
    /// between pages found the licence in a different place each time, and it is the cheapest
    /// possible thing to keep identical.</para>
    /// </summary>
    [Fact]
    public void EveryFooterListsTheSameLinksInTheSameOrder()
    {
        string[] pages =
        {
            "website/public/index.html", "website/public/404.html",
            "website/public/about/index.html", "website/public/contact/index.html",
            "website/public/privacy/index.html", "website/public/code-signing/index.html",
        };

        List<(string Text, string Href)>? expected = null;
        string? from = null;

        foreach (string path in pages)
        {
            string column = Between(Repo.Read(path), "<strong>THE SMALL PRINT</strong>", "</div>");
            List<(string Text, string Href)> links = Regex
                .Matches(column, @"<a href=""(?<href>[^""]+)""[^>]*>(?<text>[^<]+)</a>")
                .Select(m => (m.Groups["text"].Value.Trim(), m.Groups["href"].Value))
                .ToList();

            Assert.True(links.Count >= 8, $"{path} lists only {links.Count} small-print links");

            if (expected is null)
            {
                expected = links;
                from = path;
                continue;
            }

            Assert.True(expected.SequenceEqual(links),
                        $"{path} lists the small print differently from {from}:\n" +
                        $"  {from}: {string.Join(", ", expected.Select(l => l.Text))}\n" +
                        $"  {path}: {string.Join(", ", links.Select(l => l.Text))}");
        }
    }


    /// <summary>
    /// Every shot is delivered through the Image CDN, and every transformed URL names the same
    /// file the fallback does.
    ///
    /// <para>The six grid shots and the hero are 820px PNGs rendered into a slot about 360px wide
    /// on a phone, so they go out through Netlify's Image CDN as AVIF and WebP at two widths, with
    /// the original PNG left as the <c>&lt;img&gt;</c> fallback. That last part is deliberate and
    /// is what keeps two other promises intact: the bytes under <c>website/public/shots</c> are
    /// untouched, so <c>SiteShotTests</c> still holds them byte-identical to <c>docs/shots</c>,
    /// and the page's claim that running the printed <c>--searchshot</c> command reproduces the
    /// picture stays true - what the CDN changes is the encoding on the wire, not the render.</para>
    ///
    /// <para>The failure this guards against is a source pointing at a different shot from the
    /// img beside it: a reader would see one picture and a crawler would fetch another, and
    /// nothing about the page would look wrong.</para>
    /// </summary>
    [Fact]
    public void EveryShotIsServedThroughTheImageCdnAndNamesItsOwnFile()
    {
        MatchCollection pictures = Regex.Matches(Index, "<picture>(?<body>.*?)</picture>", RegexOptions.Singleline);

        int shots = Regex.Matches(Index, @"<img\s[^>]*?src=""shots/").Count;
        Assert.Equal(shots, pictures.Count);
        Assert.True(shots >= 7, $"expected every shot to be wrapped, found {shots}");

        foreach (Match picture in pictures)
        {
            string body = picture.Groups["body"].Value;

            string file = Regex.Match(body, @"<img\s[^>]*?src=""shots/(?<name>[^""]+)""").Groups["name"].Value;
            Assert.True(file.Length > 0, "a <picture> carries no <img> pointing at shots/");

            // Both formats, so a browser without AVIF still gets something smaller than the PNG.
            foreach (string format in new[] { "avif", "webp" })
            {
                Assert.Contains($@"<source type=""image/{format}""", body, StringComparison.Ordinal);
            }

            // Every transformed URL is the same file as the fallback.
            MatchCollection urls = Regex.Matches(body, @"/\.netlify/images\?url=/shots/(?<name>[^&]+)&amp;w=(?<w>\d+)&amp;fm=(?<fm>\w+)");
            Assert.True(urls.Count >= 4, $"{file} offers {urls.Count} transformed URLs, expected two per format");

            foreach (Match url in urls)
            {
                Assert.Equal(file, url.Groups["name"].Value);
            }

            // And the widest one is the real width, so the CDN is never asked to upscale.
            int declared = int.Parse(Regex.Match(body, @"<img\s[^>]*?width=""(?<w>\d+)""").Groups["w"].Value);
            Assert.Equal(declared, urls.Select(u => int.Parse(u.Groups["w"].Value)).Max());
        }
    }

    /// <summary>
    /// The IndexNow key file is named for what it contains, and the sitemap is what gets submitted.
    ///
    /// <para>The engines fetch <c>https://findra-search.netlify.app/&lt;key&gt;.txt</c> and compare
    /// its contents to the key in the submission; a mismatch is rejected silently, which is the
    /// worst shape a failure can take for something run by hand a few times a year. The key exists
    /// in one place - the file - and <c>build/Ping-IndexNow.mjs</c> reads it from there rather than
    /// holding a second copy.</para>
    /// </summary>
    [Fact]
    public void TheIndexNowKeyFileIsNamedForWhatItContains()
    {
        string[] keys = Directory.GetFiles(Repo.Path_("website/public"), "*.txt")
            .Select(Path.GetFileName)
            .Where(name => Regex.IsMatch(name!, "^[0-9a-f]{8,128}\\.txt$"))
            .ToArray()!;

        Assert.True(keys.Length == 1, $"expected exactly one IndexNow key file, found {keys.Length}");

        string key = keys[0]!.Replace(".txt", string.Empty);
        Assert.Equal(key, Repo.Read($"website/public/{keys[0]}").Trim());

        // The submitter reads the key off disk. If it ever gains a literal of its own, this is the
        // assertion that notices before the engines do.
        string script = Repo.Read("build/Ping-IndexNow.mjs");
        Assert.DoesNotContain(key, script, StringComparison.Ordinal);
    }

    private static string WithoutComments(string html) =>
        Regex.Replace(html, "<!--.*?-->", " ", RegexOptions.Singleline);

    /// <summary>The marker a block boundary leaves on both sides, so the sentence splitter treats
    /// the end of a heading the way it treats a full stop. A pilcrow, because no page here has
    /// one.</summary>
    private const char Break = '\u00b6';

    /// <summary>
    /// Whitespace flattened, and the space an inline tag leaves in front of punctuation removed.
    ///
    /// <para><c>indexed&lt;/strong&gt;, not merely</c> becomes "indexed , not merely" the moment
    /// the tag is replaced by a space, while the Markdown it came from says "indexed, not merely".
    /// Every emphasised phrase and every code span with a comma after it hits this, which is most
    /// of them.</para>
    /// </summary>
    private static string Tidy(string text) => Regex.Replace(Flat(text), @"\s+([,.;:!?])", "$1");

    /// <summary>Markup removed and entities put back, so that what remains is what a reader sees.
    /// Script and style blocks go with their contents rather than leaving their source behind as
    /// prose.</summary>
    private static string Tags(string html)
    {
        string text = Regex.Replace(html, @"<(script|style)\b.*?</\1>", " ", RegexOptions.Singleline);
        text = Regex.Replace(text, "<!--.*?-->", " ", RegexOptions.Singleline);
        // A block ends a sentence even with no full stop of its own - a heading, a bullet, a
        // table cell. Without this the heading above a paragraph and the paragraph itself flatten
        // into one run of words, and the "sentence" that comes out exists on neither side.
        text = Regex.Replace(text, @"</(h[1-6]|p|li|ul|ol|td|th|tr|pre|div|article|section)>",
                             " " + Break + " ", RegexOptions.IgnoreCase);
        text = Regex.Replace(text, "<[^>]+>", " ");
        return Tidy(text.Replace("&middot;", "·", StringComparison.Ordinal)
                        .Replace("&amp;", "&", StringComparison.Ordinal)
                        .Replace("&lt;", "<", StringComparison.Ordinal)
                        .Replace("&gt;", ">", StringComparison.Ordinal)
                        .Replace("&quot;", "\"", StringComparison.Ordinal)
                        .Replace("&copy;", "©", StringComparison.Ordinal));
    }

    /// <summary>Markdown reduced to its prose. Headings, bullets, code fences, table pipes and
    /// emphasis are markup rather than words, and the page renders them as structure.</summary>
    private static string Strip(string markdown)
    {
        // Headings, bullets and blank lines are the Markdown's own block boundaries, and they
        // become the same marker the closing tags leave on the HTML side.
        //
        // Every rule anchored to the start of a line runs BEFORE blank lines are collapsed, and
        // the order is the whole of it: collapsing "\n\n" first destroys the line start in front
        // of the FIRST bullet of every list, so that one bullet keeps its "- " while the rest lose
        // theirs - which fails on one sentence per list and looks like a content problem.
        string text = Regex.Replace(markdown, @"(?m)^```.*$", " " + Break + " ");
        text = Regex.Replace(text, @"(?m)^#{1,6}\s+(.*)$", " " + Break + " $1 " + Break + " ");
        text = Regex.Replace(text, @"(?m)^[-*]\s+", " " + Break + " ");
        // A block quote's marker, on every line of it. The generator renders the quote as an
        // ordinary paragraph inside a <blockquote>, so the page carries no marker at all;
        // leaving it here would put a stray ">" in the middle of every sentence of the one
        // paragraph the signing policy opens with, and none of them would ever match.
        text = Regex.Replace(text, @"(?m)^>\s?", "");
        text = Regex.Replace(text, @"(?m)^\|[\s|:-]+\|\s*$", " ");   // a table's rule row
        text = Regex.Replace(text, @"\n[ \t]*\n", " " + Break + " ");
        // A link is its text. The page renders `[a](mailto:a)` as "a", so leaving the target in
        // would make the two sides differ on every link that is not a bare URL.
        text = Regex.Replace(text, @"\[([^\]]+)\]\([^)]+\)", "$1");
        return Tidy(text.Replace("|", " " + Break + " ", StringComparison.Ordinal)
                        .Replace("**", "", StringComparison.Ordinal)
                        .Replace("`", "", StringComparison.Ordinal));
    }

    /// <summary>Every run of whitespace flattened to one space. Both sides are hard wrapped at
    /// columns nobody chose deliberately, and an assertion that depends on where a wrap fell breaks
    /// on the next copy-edit while the sentence it guards is still there and still correct.</summary>
    private static string Flat(string text) => Regex.Replace(text, @"\s+", " ").Trim();

    /// <summary>The block markers taken back out, for the two haystacks - a whole page, and a whole
    /// Markdown file - that are searched for a sentence rather than split into sentences.</summary>
    private static string Unbroken(string text) =>
        Flat(text.Replace(Break, ' '));

    /// <summary>
    /// The sentences worth comparing, which are the long ones.
    ///
    /// <para>A promise lives in a full sentence. Fragments - a heading, a table cell, a two-word
    /// bullet - are structure, they differ legitimately between the two renderings, and comparing
    /// them turns this into a test about formatting. Forty characters is comfortably past every
    /// heading on these three pages and comfortably under every claim on them.</para>
    /// </summary>
    private static IEnumerable<string> Sentences(string text)
    {
        // The H1 is excluded on both sides: the page carries a different one, deliberately.
        string body = Regex.Replace(text, @"(?m)\A\s*#\s+.*$", " ");

        return Regex.Split(Strip(body), @"(?<=[.!?])\s+|\s*" + Break + @"\s*")
            .Select(s => s.Trim())
            .Where(s => s.Length >= 40 && !s.Contains("http", StringComparison.Ordinal));
    }
}
